-- R01 teacher-note revision batch
-- Updates the 21 questions identified in the teacher feedback CSV.
-- Existing question_code and UUIDs are preserved; notes remain attached.
-- All items remain draft pending another teacher review.
begin;
insert into public.reading_question_bank
(question_code,category,cefr_level,topic,skill,passage,prompt,options,correct_option,rationale,difficulty,estimated_seconds,status)
values
('A2-002','R01','A2','Health and Nutrition','Identifying advice in a short notice','GREEN LEAF CAFÉ
Our lunch menu changes every Monday.
This week, we are offering chicken rice, vegetable soup and fresh fruit.
Customers with food allergies should speak to an employee before ordering.
Please order at the counter. Your food will be brought to your table.','What should a customer with a food allergy do before choosing a meal?','[{"label":"A","text":"Ask someone who works at the café for advice."},{"label":"B","text":"Choose the vegetable soup because it contains no meat."},{"label":"C","text":"Wait until the meal arrives before explaining the allergy."},{"label":"D","text":"Return on Monday when the menu has changed."}]'::jsonb,'A','The notice advises customers with allergies to speak to an employee before ordering.','core',45,'draft'),
('A2-008','R01','A2','Consumer Economics','Understanding conditions in a returns policy','CITY SPORTS – RETURNS
You may return an item within 14 days of purchase. It must be unused and have its original labels. Shoes worn outdoors cannot be returned unless they are faulty. Please bring your receipt when visiting the shop.','Which customer meets the shop''s conditions for returning a pair of shoes?','[{"label":"A","text":"A customer who wore the shoes outside once, cleaned them carefully and kept the box and labels."},{"label":"B","text":"A customer who bought the shoes several months ago and has worn them only indoors."},{"label":"C","text":"A customer whose shoes are unused but who has thrown away the original labels."},{"label":"D","text":"A customer returning unused shoes with their labels and receipt, bought ten days ago."}]'::jsonb,'D','The shoes in option D are unused, still labelled and within the 14-day period. The receipt is also available.','core',60,'draft'),
('A2-016','R01','A2','Technology and Society','Following a sequence of instructions','PHONE REPAIR DESK
Before handing in your phone, switch it off and remove its case. Take out your SIM card and keep it with you. The technician will send you a message when the repair is complete.','What should you do before leaving your phone at the repair desk?','[{"label":"A","text":"Switch it off, remove the case and keep the SIM card."},{"label":"B","text":"Switch it off, leave the case on and give the SIM card to the technician."},{"label":"C","text":"Leave it switched on, remove the case and keep the SIM card."},{"label":"D","text":"Remove the SIM card, leave the phone on and ask the technician to switch it off."}]'::jsonb,'A','The instructions require all three actions: switch off the phone, remove its case and keep the SIM card.','core',55,'draft'),
('A2-018','R01','A2','Transportation and Travel','Inferring who may have difficulty','TRAIN STATION NOTICE
The ticket office will close early this Friday for staff training. Passengers can still buy tickets from the machines near the main entrance. The machines accept bank cards only. Station employees can show passengers how to use them, but cannot sell tickets themselves.','Who may have difficulty buying a ticket on Friday?','[{"label":"A","text":"A passenger who has a bank card but has never used a ticket machine."},{"label":"B","text":"A passenger who has cash but no bank card and needs to buy a ticket."},{"label":"C","text":"A passenger who arrives early and asks an employee to explain the machine."},{"label":"D","text":"A passenger who has already bought a ticket before arriving at the station."}]'::jsonb,'B','The ticket office is closed and the machines accept bank cards only. Staff can help with the machines but cannot sell tickets.','core',60,'draft'),
('A2-019','R01','A2','Environment and Pollution','Interpreting park rules','PARK NOTICE
Dogs are welcome in the park. Near the playground, owners must keep them on a lead. Please clean up after your dog. The small garden beside the pond is closed to visitors while new plants are growing.','Which statement about dogs in the park is correct?','[{"label":"A","text":"Dogs must stay on a lead throughout the entire park."},{"label":"B","text":"Owners may let dogs run freely near the playground."},{"label":"C","text":"Dogs cannot enter the small garden beside the pond."},{"label":"D","text":"Dogs are allowed to play in the garden if their owners stay nearby."}]'::jsonb,'C','The garden beside the pond is closed to all visitors, including people with dogs. The lead rule applies near the playground, not throughout the whole park.','core',55,'draft'),
('A2-020','R01','A2','Health and Nutrition','Understanding what to do first','SCHOOL HEALTH ROOM
If you feel unwell during the school day, tell your teacher before coming to the health room. Please do not take medicine from another student. The nurse is available until 3 p.m.','A student begins to feel ill during a lesson. What should the student do first?','[{"label":"A","text":"Ask a friend to share some medicine."},{"label":"B","text":"Go home without telling anyone."},{"label":"C","text":"Let the teacher know that they are feeling unwell."},{"label":"D","text":"Wait until 3 p.m. and then visit the health room."}]'::jsonb,'C','The notice says students should tell their teacher before going to the health room.','core',45,'draft'),
('A2-021','R01','A2','Media and Youth','Recognising requirements for an entry','PHOTOGRAPHY COMPETITION
Show us your best picture of everyday life in our town. Photos must be your own work. Anyone who can be recognised in a picture must have agreed to be photographed. Send your entry to the school media club.','Which photograph follows the competition rules?','[{"label":"A","text":"A student''s own photo of a town market, with permission from everyone who can be recognised."},{"label":"B","text":"A photo taken by the student''s parent, which the student has edited and entered."},{"label":"C","text":"A student''s own photo of a stranger who did not know they were being photographed."},{"label":"D","text":"A picture downloaded from a travel website showing a street in the student''s town."}]'::jsonb,'A','The photograph must be the student''s own work, and recognisable people must have agreed to appear in it.','core',60,'draft'),
('A2-022','R01','A2','Cities and Housing','Matching a person to accommodation','FLAT SHARE
A room is available in a shared flat near the university. The room is unfurnished, and the kitchen is shared with two other people. Smoking is not allowed inside the building. The nearest bus stop is a long walk away. Contact May to arrange a visit.','Who would be the best fit for this room?','[{"label":"A","text":"A university student who smokes and wants to smoke in their bedroom."},{"label":"B","text":"An exchange student who has their own furniture and is happy to share a kitchen."},{"label":"C","text":"A student who wants to live alone and have a private kitchen."},{"label":"D","text":"A student who depends on taking the bus every day and cannot walk far."}]'::jsonb,'B','The room is unfurnished, so someone with their own furniture is suitable. The person must also be comfortable sharing a kitchen.','core',60,'draft'),
('A2-025','R01','A2','Space Exploration','Identifying a true statement','SCIENCE MUSEUM
The space exhibition is temporarily closed on Monday morning while new displays are installed. It will reopen at 1 p.m. The rest of the museum will be open as usual.','Which statement is true about the museum on Monday morning?','[{"label":"A","text":"The whole museum will remain closed until 1 p.m."},{"label":"B","text":"Visitors can explore the museum''s other areas while the space exhibition is closed."},{"label":"C","text":"The space exhibition is being removed and will not reopen."},{"label":"D","text":"All the museum''s exhibitions are closed while the new displays are installed."}]'::jsonb,'B','Only the space exhibition is closed. The notice says the rest of the museum will be open as usual.','core',50,'draft'),
('A2-026','R01','A2','Consumer Economics','Applying conditions in a returns policy','BOOKSHOP RETURNS
Books may be exchanged within seven days of purchase if they are unread and in good condition. Please bring your receipt. Dictionaries and other reference books cannot be exchanged.','Which customer can exchange a book?','[{"label":"A","text":"A customer with a dictionary bought yesterday and its receipt."},{"label":"B","text":"A customer with an unread novel bought five days ago, in good condition and with the receipt."},{"label":"C","text":"A customer with a damaged novel bought yesterday and with the receipt."},{"label":"D","text":"A customer with an unread novel bought two weeks ago and with the receipt."}]'::jsonb,'B','The novel in option B is unread, in good condition, within seven days and the receipt is available.','core',60,'draft'),
('A2-027','R01','A2','Technology and Society','Understanding the purpose of a message','MESSAGE FROM LEO
Hi Nina, I uploaded the group presentation last night, but I noticed that one picture was missing. I''ve added it now. Please check the latest version before our meeting.','Why did Leo send Nina this message?','[{"label":"A","text":"To tell her that he has finished the presentation and that it is ready to check."},{"label":"B","text":"To explain that Nina forgot to add a picture to the presentation."},{"label":"C","text":"To let her know that he corrected the presentation by adding the missing picture."},{"label":"D","text":"To ask her to add the missing picture before their meeting."}]'::jsonb,'C','Leo noticed a missing picture and says that he has added it himself. He wants Nina to check the updated version.','core',55,'draft'),
('A2-028','R01','A2','Education and Learning','Choosing a suitable place from a library notice','LIBRARY REMINDER
The glass study room is available for group discussions. The main reading area is kept quiet for individual work. Books that you have finished using should be placed on the return trolley beside the entrance, rather than put back on the shelves. Students may choose any available seat in the main reading area.','You want to work quietly by yourself and read a library book. Where should you go?','[{"label":"A","text":"To the glass study room, where groups can discuss their work."},{"label":"B","text":"To the return trolley beside the entrance."},{"label":"C","text":"To the main reading area, where individual study is expected."},{"label":"D","text":"To the shelves, where students return books after reading."}]'::jsonb,'C','The main reading area is for quiet individual work, making it the best place for someone studying alone.','core',55,'draft'),
('A2-029','R01','A2','Climate and Weather','Making an inference from an update','WEATHER UPDATE
Heavy rain is expected this afternoon. The school football practice will move from the main field to the covered court. Students should bring their usual sports clothes. Practice will continue at the normal time.','Which statement is true?','[{"label":"A","text":"Football practice has been cancelled because of the expected rain."},{"label":"B","text":"Students need to bring an extra set of sports clothes."},{"label":"C","text":"The school has another playing area that can be used when the main field is unsuitable."},{"label":"D","text":"Students must bring raincoats to wear during the practice."}]'::jsonb,'C','Practice is continuing in a different location. This shows that the school has a covered area as well as the main field.','core',60,'draft'),
('A2-031','R01','A2','Education and Learning','Interpreting opening times','ART ROOM NOTICE
The art room will be closed from 1 p.m. onwards today while the walls are painted. Students who need materials for their projects should collect them before lunch.','When can students collect their materials?','[{"label":"A","text":"After 1 p.m., while the room is closed for painting."},{"label":"B","text":"Tomorrow morning, after the work has finished."},{"label":"C","text":"Before 1 p.m., while the room is still open."},{"label":"D","text":"Only after the paint has completely dried."}]'::jsonb,'C','The room closes from 1 p.m., and students are asked to collect materials before lunch.','core',45,'draft'),
('A2-033','R01','A2','Food Production','Understanding conditions for a free sample','MARKET STALL
Visitors are welcome to try a piece of fruit before deciding whether to buy anything. Samples are free. Please take one of the small paper cups from the counter. The fruit arranged on the display table is for looking at, so ask the seller if you would like a sample.','Which statement is true?','[{"label":"A","text":"Visitors must buy some fruit after trying a sample."},{"label":"B","text":"Customers may take pieces directly from the display table."},{"label":"C","text":"A small paper cup should be used when trying a sample."},{"label":"D","text":"The fruit on display is free for visitors to take home."}]'::jsonb,'C','The notice says samples are free but asks visitors to use the paper cups and not touch the display fruit.','core',50,'draft'),
('A2-035','R01','A2','Technology and Society','Understanding the reason for a change','EMAIL FROM THE IT TEAM
We have changed the school Wi-Fi password because the old one had been shared widely. Students can get the new password from their homeroom teacher. Please do not share it with visitors; guests have separate temporary login codes.','Why did the school change the Wi-Fi password?','[{"label":"A","text":"The school discovered that someone had broken into its computer system."},{"label":"B","text":"Too many people already knew the previous password."},{"label":"C","text":"Visitors are no longer allowed to use the school internet."},{"label":"D","text":"The school has replaced its network equipment."}]'::jsonb,'B','The email directly explains that the old password had been shared widely. Visitors now use separate temporary codes.','core',60,'draft'),
('A2-036','R01','A2','Cities and Housing','Understanding what is not provided','RENTAL ROOM NOTICE
The room is available from the beginning of next month. A desk and wardrobe are provided, but there is no mattress or bedding. Tenants should bring what they need for sleeping. The building has a shared laundry room.','What does a new tenant need to provide?','[{"label":"A","text":"A desk and a place to hang clothes."},{"label":"B","text":"A mattress and something warm to cover themselves with."},{"label":"C","text":"A washing machine for the shared laundry room."},{"label":"D","text":"A wardrobe for storing personal belongings."}]'::jsonb,'B','The room already has a desk and wardrobe, but the tenant must arrange a mattress and bedding.','core',50,'draft'),
('A2-037','R01','A2','Environment and Pollution','Interpreting a request using paraphrase','SCHOOL GARDEN
The flowers in the front garden help attract butterflies and other insects. Please leave the plants where they are. Visitors may take photographs from the marked path, but should not enter the flower beds.','Which visitor is following the garden''s instructions?','[{"label":"A","text":"A visitor who takes a flower home after photographing it."},{"label":"B","text":"A visitor who steps between the plants to get a closer picture."},{"label":"C","text":"A visitor who stays on the path and takes a photograph without touching the flowers."},{"label":"D","text":"A visitor who moves a plant so that a butterfly can be seen more clearly."}]'::jsonb,'C','Visitors should keep to the path and leave the plants in place. Option C follows both instructions.','core',60,'draft'),
('A2-040','R01','A2','Climate and Weather','Inferring a reason for a change','HIKING GROUP MESSAGE
After last night''s rain, the upper path near the waterfall has become slippery in several places. The group will take the lower forest route instead. Please wear shoes with a good grip, as some sections may still be wet.','What can you understand about the group''s decision?','[{"label":"A","text":"The upper path is no longer suitable for the group in its present condition."},{"label":"B","text":"The waterfall area has been closed to visitors for the whole season."},{"label":"C","text":"The lower route is the only path that reaches the waterfall."},{"label":"D","text":"The group has changed its plan because it wants to avoid walking in the forest."}]'::jsonb,'A','The rain has left several parts of the upper path slippery, so the group chooses another route for safety.','core',60,'draft'),
('A2-041','R01','A2','Health and Nutrition','Interpreting a food safety warning','FOOD LABEL
This product is sealed to keep it fresh. After opening, keep it in the refrigerator and use it within three days. Do not eat the product if the safety seal is missing or damaged when you open the package.','When should someone avoid eating the product?','[{"label":"A","text":"When it has been kept in the refrigerator after opening."},{"label":"B","text":"When it is going to be used within three days."},{"label":"C","text":"When the package has no complete safety seal at the time it is opened."},{"label":"D","text":"When the product has just been opened for the first time."}]'::jsonb,'C','The label says not to eat the product if its safety seal is missing or damaged when the package is opened.','core',55,'draft'),
('A2-043','R01','A2','Technology and Society','Following instructions about shared equipment','COMPUTER ROOM
Before logging out, save any work you want to keep. Return the headphones to the labelled storage box so the next class can find them. Leave the keyboard and mouse on the desk, and do not move the monitor. Please push your chair under the desk when you leave.','Which piece of equipment should be put away after the lesson?','[{"label":"A","text":"The keyboard, ready for the next student to use."},{"label":"B","text":"The mouse, so it can be stored with other equipment."},{"label":"C","text":"The monitor, which should be moved away from the desk."},{"label":"D","text":"The headphones, which belong in the labelled storage box."}]'::jsonb,'D','The headphones must be returned to the labelled storage box. The keyboard, mouse and monitor should remain at the desk.','core',undefined,'draft')
on conflict (question_code) do update set
 category=excluded.category,
 cefr_level=excluded.cefr_level,
 topic=excluded.topic,
 skill=excluded.skill,
 passage=excluded.passage,
 prompt=excluded.prompt,
 options=excluded.options,
 correct_option=excluded.correct_option,
 rationale=excluded.rationale,
 difficulty=excluded.difficulty,
 estimated_seconds=excluded.estimated_seconds,
 status='draft',
 updated_at=now();
commit;

-- Verification: should return 21 rows, all still draft.
select question_code, cefr_level, status, correct_option, estimated_seconds
from public.reading_question_bank
where question_code in ('A2-002','A2-008','A2-016','A2-018','A2-019','A2-020','A2-021','A2-022','A2-025','A2-026','A2-027','A2-028','A2-029','A2-031','A2-033','A2-035','A2-036','A2-037','A2-040','A2-041','A2-043')
order by question_code;
